            .map_err(|e| AppError::Internal(e.to_string()))?;

    let moot: i64 =
        sqlx::query_scalar("SELECT COUNT(*) FROM logs WHERE event_type = 'task_rejected'")
            .fetch_one(pool)
            .await
            .map_err(|e| AppError::Internal(e.to_string()))?;

    Ok(vec![
        TaskStatusCount {
            status: TaskLifecycleStatus::Active,
            count: active as usize,
